/* ProductViewLogMapper.existsRecentView */
SELECT EXISTS (
    SELECT 1 FROM PRODUCT_VIEW_LOG
     WHERE PRD_SN = #{prdSn}
       AND VISITOR_KEY = #{visitorKey}
       AND PRD_VIEW_LOG_REG_DT > #{since}
)

